package vn.cinema;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import vn.cinema.app.Application;import vn.cinema.service.MovieService;import vn.cinema.dto.MovieRequest;import java.time.LocalDate;import java.util.List;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(classes=Application.class)class MovieTest{@Autowired MovieService s;@Test void createAndReadMovieAndProtectCategory(){var c=s.category(null,"Phiêu lưu","");var d=LocalDate.now();var m=s.save(null,new MovieRequest("Phim kiểm thử","Test","Nội dung",120,d,d.plusDays(30),"T13","Tiếng Việt","Việt Nam","Đạo diễn","Diễn viên","","","","NOW_SHOWING",List.of(c.id)));assertThat(s.get(m.id).title).isEqualTo("Phim kiểm thử");assertThat(s.list("kiểm",null,null)).hasSize(1);assertThatThrownBy(()->s.deleteCategory(c.id)).hasMessageContaining("sử dụng");}}